// Runtime shape of web/public/scenes/manifest.json (generated by
// tools/scenes/prepare.py from data/scenes/scenes.json).

export interface SceneDefinition {
  id: string;
  title: string;
  description: string;
  /** Longitude in degrees, inside the Amazon rectangle. */
  lon: number;
  /** Latitude in degrees, inside the Amazon rectangle. */
  lat: number;
  /** Image path relative to web/public, for example "scenes/birds/birds.jpg". */
  image: string;
  imageAlt: string;
  /** Loop path relative to web/public. */
  loop: string;
  /** Target loop volume, 0..1. */
  loopGain: number;
  imageCredit: string | null;
  audioCredit: string | null;
}

export interface ScenesManifest {
  version: number;
  transition: { id: string; file: string };
  scenes: SceneDefinition[];
}
